/// Matrix multiply-add operation: I32 = I8 * I8 + I32, C5XX
template <typename ElementC_>
struct MacaMma<int8_t, layout::RowMajor,
               int8_t, layout::ColumnMajor,
               ElementC_, layout::ColumnMajor,
               mctlass::arch::Sm80> {
    using Shape = gemm::GemmShape<16, 16, 16>;
    using ElementA = int8_t;
    using LayoutA = layout::RowMajor;
    using FragmentA = int32_t;
    using ElementB = int8_t;
    using LayoutB = layout::ColumnMajor;
    using FragmentB = int32_t;
    using ElementC = ElementC_;
    using LayoutC = layout::ColumnMajor;
    using FragmentC = __NATIVE_VECTOR__(4, int32_t);
    using Arch = mctlass::arch::Sm80;
    using ElementAccumulator = int32_t;

    MCTLASS_DEVICE
    void operator()(
        FragmentC &d,
        FragmentA const &a,
        FragmentB const &b,
        FragmentC const &c
    ) const {
#if defined(__MACA_ARCH__) && (__MACA_ARCH__ == 1000)
        // not supported in 1500
        d = __builtin_mxc_mma_16x16x16i8(a, b, c);
#endif

load_matrix_sync(fragment<matrix_a, 16, 16, 16, signed char, row_major> &f,
                 const signed char *p, unsigned int ldm) {
  unsigned row = __lane_id() & 0xf;
  unsigned col = ((__lane_id() >> 4) << 2);
  f.x[0] = *(int *)(p + row * ldm + col);

load_matrix_sync(fragment<matrix_b, 16, 16, 16, signed char, col_major> &f,
                 const signed char *p, unsigned int ldm) {
  unsigned row = ((__lane_id() >> 4) << 2);
  unsigned col = __lane_id() & 0xf;
  f.x[0] = *(int *)(p + col * ldm + row);
}

store_matrix_sync(int *p, const fragment<accumulator, 16, 16, 16, int> &f,
                  unsigned int ldm, layout_t layout) {
  unsigned row = (__lane_id() >> 4) << 2;
  unsigned col = __lane_id() & 0xf;
  if (layout_t::mem_row_major == layout) {
    p[row * ldm + col] = f.x[0];
    p[(row + 1) * ldm + col] = f.x[1];
    p[(row + 2) * ldm + col] = f.x[2];
    p[(row + 3) * ldm + col] = f.x[3];
  } else {
    p[col * ldm + row] = f.x[0];
    p[col * ldm + row + 1] = f.x[1];
    p[col * ldm + row + 2] = f.x[2];
    p[col * ldm + row + 3] = f.x[3];
  }

