#include <mcr/mc_runtime.h>
#include <cstdint>
#include <cstdio>
#include <vector>
#include <random>
#include <cstdlib>
using I4 = int32_t __attribute__((ext_vector_type(4)));
#define CHECK(x) do { auto rc=(x); if(rc!=mcSuccess){std::fprintf(stderr,"%s: %s\n",#x,mcGetErrorString(rc));return 1;} }while(0)
__global__ void probe(const int8_t* a,const int8_t* b,int32_t* out,int k,int bias) {
  int lane=threadIdx.x, mn=lane%16, kp=(lane/16)*4;
  I4 accum={bias,bias+1,bias+2,bias+3};
  for(int k0=0;k0<k;k0+=16){
    uint32_t aw=0,bw=0;
    for(int j=0;j<4;++j){
      aw|=uint32_t(uint8_t(a[mn*k+k0+kp+j]))<<(8*j);
      bw|=uint32_t(uint8_t(b[mn*k+k0+kp+j]))<<(8*j);
    }
    accum=__builtin_mxc_mma_16x16x16i8(int32_t(aw),int32_t(bw),accum);
  }
  for(int j=0;j<4;++j)out[((lane/16)*4+j)*16+mn]=accum[j];
}
int main(){
  mcDeviceProp_t prop{};CHECK(mcGetDeviceProperties(&prop,0));
  if(prop.warpSize!=64){std::fprintf(stderr,"Unexpected warpSize=%d\n",prop.warpSize);return 1;}
  std::mt19937 rng(20261020);int cases=0;int64_t checked=0;
  for(int k:{16,32,64,256}) for(int mode=0;mode<5;++mode){
    std::vector<int8_t>a(16*k),b(16*k);std::vector<int32_t>out(256);
    for(int i=0;i<16*k;++i){
      a[i]=mode==1?-128:mode==2?127:mode==3?0:mode==4?int8_t((i/k+3*(i%k))%127-63):int8_t(rng()%256-128);
      b[i]=mode==1?-128:mode==2?-128:mode==3?127:mode==4?int8_t((5*(i/k)+7*(i%k))%127-63):int8_t(rng()%256-128);
    }
    int8_t *da,*db;int32_t*dc;CHECK(mcMalloc((void**)&da,a.size()));CHECK(mcMalloc((void**)&db,b.size()));CHECK(mcMalloc((void**)&dc,1024));
    CHECK(mcMemcpy(da,a.data(),a.size(),mcMemcpyHostToDevice));CHECK(mcMemcpy(db,b.data(),b.size(),mcMemcpyHostToDevice));
    int bias=mode-2;probe<<<1,64>>>(da,db,dc,k,bias);CHECK(mcGetLastError());CHECK(mcDeviceSynchronize());
    CHECK(mcMemcpy(out.data(),dc,1024,mcMemcpyDeviceToHost));
    for(int m=0;m<16;++m)for(int n=0;n<16;++n){
      int64_t expected=bias+(m%4);for(int p=0;p<k;++p)expected+=int64_t(a[m*k+p])*b[n*k+p];
      if(out[m*16+n]!=expected){std::fprintf(stderr,"FAIL k=%d mode=%d m=%d n=%d got=%d expected=%lld\n",k,mode,m,n,out[m*16+n],(long long)expected);return 1;}
      ++checked;
    }
    CHECK(mcFree(da));CHECK(mcFree(db));CHECK(mcFree(dc));++cases;
  }
  std::printf("{\"status\":\"PASS\",\"cases\":%d,\"checked_int32_outputs\":%lld,\"warp_size\":%d,\"mma\":\"__builtin_mxc_mma_16x16x16i8\",\"lane_input\":\"mn=lane%%16,k=4*(lane/16)+byte\",\"lane_output\":\"m=4*(lane/16)+component,n=lane%%16\"}\n",cases,(long long)checked,prop.warpSize);
}
